import { useState } from 'react';
import { Download, Trash2 } from 'lucide-react';
import { accountApi, ApiError } from '../../api/client';
import { clearSession } from '../../api/session';
import { Button, Field, StatusMessage } from '../../design/components';
import { useI18n } from '../../i18n/I18n';
import { caseErrorText } from '../cases/caseErrors';

/** Self-service GDPR-style data operations from ABB-28. Export is generated by the server with role redaction. */
export function AccountDataPanel() {
  const { t } = useI18n();
  const [open, setOpen] = useState(false); const [password, setPassword] = useState(''); const [confirmed, setConfirmed] = useState(false);
  const [busy, setBusy] = useState<'export' | 'delete' | null>(null); const [error, setError] = useState('');
  async function exportData() {
    setBusy('export'); setError('');
    try {
      const data = await accountApi.export();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob); const a = document.createElement('a');
      a.href = url; a.download = `cropstory-account-${data.exported_at.slice(0, 10)}.json`; a.click(); URL.revokeObjectURL(url);
    } catch (err) { setError(caseErrorText(err, t)); } finally { setBusy(null); }
  }
  async function deleteAccount(e: React.FormEvent) {
    e.preventDefault(); if (!password || !confirmed) return;
    setBusy('delete'); setError('');
    try { await accountApi.delete(password); clearSession(); }
    catch (err) { setError(err instanceof ApiError && err.status === 401 ? t('account.passwordIncorrect') : caseErrorText(err, t)); setBusy(null); }
  }
  return <section className="panel account-data" aria-labelledby="account-data-h">
    <div className="section-head"><h2 id="account-data-h">{t('account.dataTitle')}</h2><p>{t('account.dataLead')}</p></div>
    <div className="actions"><Button icon={<Download aria-hidden="true" />} busy={busy === 'export'} onClick={exportData}>{t('account.export')}</Button><Button variant="text" icon={<Trash2 aria-hidden="true" />} aria-expanded={open} onClick={() => setOpen((v) => !v)}>{t('account.deleteOpen')}</Button></div>
    {error && <StatusMessage tone="error" title={t('account.error')}>{error}</StatusMessage>}
    {open && <form className="danger-zone stack" onSubmit={deleteAccount}>
      <StatusMessage tone="error" title={t('account.deleteTitle')}>{t('account.deleteBody')}</StatusMessage>
      <Field label={t('auth.password')} type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} />
      <label className="check"><input type="checkbox" checked={confirmed} onChange={(e) => setConfirmed(e.target.checked)} /><span>{t('account.deleteConfirm')}</span></label>
      <div className="actions"><Button type="submit" variant="secondary" disabled={!password || !confirmed} busy={busy === 'delete'}>{t('account.deleteAction')}</Button><Button variant="text" onClick={() => { setOpen(false); setPassword(''); setConfirmed(false); }}>{t('cases.cancel')}</Button></div>
    </form>}
  </section>;
}
